<?php
/** Template Name: Bảng giá Spa */
get_header();
$services = get_posts(array('post_type'=>'spa_service','post_status'=>'publish','numberposts'=>-1,'orderby'=>'menu_order title','order'=>'ASC'));
$packages = get_posts(array('post_type'=>'spa_package','post_status'=>'publish','numberposts'=>-1,'orderby'=>'menu_order title','order'=>'ASC'));
$terms = get_terms(array('taxonomy'=>'spa_service_cat','hide_empty'=>false));
?>
<section class="page-hero"><div class="container"><span class="eyebrow">Minh bạch & rõ ràng</span><h1 class="page-title">Bảng giá dịch vụ</h1><p class="muted">Tham khảo giá và lựa chọn dịch vụ phù hợp. Giá chưa được cập nhật sẽ hiển thị là “Liên hệ”.</p></div></section>
<main class="content-area container pricing-page">
<div class="pricing-tools"><label class="pricing-search-label">Tìm dịch vụ<input id="pricing-search" type="search" placeholder="Ví dụ: massage, chăm sóc da..."></label><label class="pricing-search-label">Nhóm dịch vụ<select id="pricing-category"><option value="all">Tất cả nhóm</option><?php if(!is_wp_error($terms)) foreach($terms as $term): ?><option value="<?php echo esc_attr(sanitize_title($term->name)); ?>"><?php echo esc_html($term->name); ?></option><?php endforeach; ?><option value="goi-lieu-trinh">Gói liệu trình</option></select></label><label class="pricing-search-label">Khoảng giá<select id="pricing-price"><option value="all">Tất cả mức giá</option><option value="under300">Dưới 300.000đ</option><option value="300to500">300.000–500.000đ</option><option value="over500">Trên 500.000đ</option><option value="contact">Liên hệ</option></select></label></div>
<?php if($services): ?><section class="pricing-section"><h2>Dịch vụ lẻ</h2><div class="pricing-table-wrap"><table class="pricing-table"><thead><tr><th>Dịch vụ</th><th>Thời lượng</th><th>Giá niêm yết</th><th>Giá ưu đãi</th><th></th></tr></thead><tbody><?php foreach($services as $service): $price=get_post_meta($service->ID,'_spa_price',true); $sale=get_post_meta($service->ID,'_spa_sale_price',true); $duration=get_post_meta($service->ID,'_spa_duration',true); $cats=get_the_terms($service->ID,'spa_service_cat'); $cat_names=array(); if($cats&&!is_wp_error($cats)) foreach($cats as $cat) $cat_names[]=sanitize_title($cat->name); $category_data=implode(' ',$cat_names); $effective=($sale!=='' && (int)$sale>0)?(int)$sale:(($price!=='' && (int)$price>0)?(int)$price:0); ?><tr class="pricing-row" data-name="<?php echo esc_attr(mb_strtolower($service->post_title)); ?>" data-category="<?php echo esc_attr($category_data); ?>" data-price="<?php echo esc_attr($effective); ?>"><td><strong><?php echo esc_html($service->post_title); ?></strong><small><?php echo esc_html(wp_trim_words($service->post_excerpt ?: wp_strip_all_tags($service->post_content),14)); ?></small></td><td><?php echo $duration?esc_html($duration):'—'; ?></td><td><?php echo $price!==''&&(int)$price>0?esc_html(number_format_i18n((int)$price).' đ'):'—'; ?></td><td class="price"><?php echo $sale!==''&&(int)$sale>0?esc_html(number_format_i18n((int)$sale).' đ'):($effective?esc_html(number_format_i18n($effective).' đ'):'Liên hệ'); ?></td><td><a class="btn btn-outline btn-small" href="<?php echo esc_url(add_query_arg('dich-vu',$service->ID,home_url('/dat-lich/'))); ?>">Đặt lịch</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php else: ?><div class="empty-state"><h2>Chưa có dữ liệu dịch vụ</h2><p>Hãy thêm dịch vụ và giá trong WordPress Admin → Dịch vụ Spa. Bảng giá sẽ tự cập nhật.</p><a class="btn" href="<?php echo esc_url(admin_url('post-new.php?post_type=spa_service')); ?>">Thêm dịch vụ trong quản trị</a></div><?php endif; ?>
<?php if($packages): ?><section class="pricing-section"><h2>Gói liệu trình & combo</h2><div class="cards"><?php foreach($packages as $package): ?><article class="card"><a href="<?php echo esc_url(get_permalink($package)); ?>"><div class="card-image"><?php if(has_post_thumbnail($package->ID)) echo get_the_post_thumbnail($package->ID,'large'); else { ?><img src="<?php echo esc_url(get_template_directory_uri().'/assets/images/spa-album-room.jpg'); ?>" alt="<?php echo esc_attr($package->post_title); ?>" loading="lazy"><?php } ?></div></a><div class="card-body"><h3><a href="<?php echo esc_url(get_permalink($package)); ?>"><?php echo esc_html($package->post_title); ?></a></h3><p><?php echo esc_html(wp_trim_words($package->post_excerpt ?: wp_strip_all_tags($package->post_content),20)); ?></p><?php $p=beaute_spa_price($package->ID); $s=beaute_spa_price($package->ID,true); ?><p class="price"><?php echo $s?esc_html($s):($p?esc_html($p):'Liên hệ để biết giá'); ?> <?php if($s&&$p): ?><del class="muted"><?php echo esc_html($p); ?></del><?php endif; ?></p><a class="btn" href="<?php echo esc_url(add_query_arg('goi',$package->ID,home_url('/dat-lich/'))); ?>">Chọn gói</a></div></article><?php endforeach; ?></div></section><?php endif; ?>
<p class="pricing-note">Giá hiển thị được quản trị viên cập nhật. Vui lòng liên hệ spa để xác nhận giá và điều kiện ưu đãi trước khi sử dụng dịch vụ.</p>
</main><?php get_footer(); ?>
